select status, case when balance >= 72000 then 'high' when balance >= 17000 then 'mid' else 'low' end as balance_bucket, count(balance) as balance_count, min(opened_date) as min_opened_date from accounts where status in ('OPEN', 'FROZEN', 'CLOSED') and status in ('FROZEN', 'OPEN', 'CLOSED') group by status, case when balance >= 72000 then 'high' when balance >= 17000 then 'mid' else 'low' end having count(balance) < 4;
